import{_ as o,o as s,c as t,a5 as r}from"./chunks/framework.DSg0KOwT.js";const p=JSON.parse('{"title":"Regression metric keys","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/getting-started/regression-metric-keys.md","filePath":"user-guide/getting-started/regression-metric-keys.md"}'),i={name:"user-guide/getting-started/regression-metric-keys.md"};function d(c,e,a,l,n,u){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="regression-metric-keys" tabindex="-1">Regression metric keys <a class="header-anchor" href="#regression-metric-keys" aria-label="Permalink to &quot;Regression metric keys&quot;">​</a></h1><p>The metric keys that a regression metric or regression budget accepts.</p><p><code>--regression-metric</code>, <code>--regression-budget</code> and the <code>--budgets</code> file (and the MCP <code>evaluate_budgets</code> tool&#39;s <code>regressionMetric</code>) take one of these keys; the default for <code>--regression-metric</code> is <code>wallClock</code>:</p><ul><li><code>wallClock</code>: wall-clock duration</li><li><code>executorRunTime</code>: summed executor run time</li><li><code>shuffleSpill</code>: memory spill (Spark&#39;s <code>memoryBytesSpilled</code>)</li><li><code>diskSpill</code>: disk spill (Spark&#39;s <code>diskBytesSpilled</code>)</li><li><code>gcTime</code>: JVM GC time</li><li><code>taskSkew</code>: p95 task skew</li><li><code>failedTaskRate</code>: failed-task rate</li><li><code>executorCpuTime</code>: summed executor CPU time, in milliseconds (unavailable for a run whose log never recorded it)</li><li><code>allocatedCoreHours</code>: executor cores times hours alive, see <a href="./ci-and-automation.html#allocation">Allocation</a></li></ul><p>Whole-run spill keys are <code>shuffleSpill</code> and <code>diskSpill</code>. Per-stage budgets use <code>memoryBytesSpilled</code> and <code>diskBytesSpilled</code> instead.</p><p>Four more keys, <code>inputBytes</code>, <code>outputBytes</code>, <code>taskCount</code> and <code>executorsAdded</code>, measure workload volume rather than performance. They have no better or worse direction, so a regression budget on one of them reports <code>inconclusive</code> whenever the value changes, and passes when it doesn&#39;t.</p>',6)])])}const g=o(i,[["render",d]]);export{p as __pageData,g as default};
